def top_words(text, min_length=1):
    """The five most common words, most common first, ties alphabetical."""
    counts = {}
    for word in words(text):
        if len(word) < min_length:
            continue
        if word in counts:
            counts[word] = counts[word] + 1
        else:
            counts[word] = 1

def test_at_most_five(self):
    self.assertEqual(len(top_words("a b c d e f g")), 5)

def test_min_length_skips_short_words(self):
    self.assertEqual(
        top_words("a bb ccc dddd bb ccc dddd", min_length=3),
        [("ccc", 2), ("dddd", 2)],
    )

def test_min_length_default_keeps_all(self):
    self.assertEqual(top_words("a bb a"), [("a", 2), ("bb", 1)])
